def solve(inp):
    g=[r[:] for r in inp]; H=len(g); W=len(g[0])
    seeds=[]; tpl_seqs=[]
    for i,r in enumerate(g):
        # maximal runs of nonzero values
        c=0
        while c<W:
            if r[c]:
                c0=c
                while c<W and r[c]: c+=1
                vals=[(x,c0-(c-c0)) for x in r[c0:c]]
                seq=[v for _,v in vals]
                # anchor: find seeds mapping: value v has index pos in seq; place so seed at pos
                if len(seq)>1: tpl_seqs.append((i,seq)); continue
                for j,x in enumerate(r):
                    pass
            c+=1
        # collect single-value seeds
        nz=[(j,x) for j,x in enumerate(r) if x]
        if len(nz)==1: seeds.append((i,nz[0][0],nz[0][1]))
    out=[r[:] for r in g]
    for t,(i,seq) in enumerate(tpl_seqs):
        anchors={}  # val -> index in seq
        for k,v in enumerate(seq): anchors[v]=k
        for si,sj,sv in seeds:
            if sv in anchors:
                start=sj-anchors[sv]
                for k,v in enumerate(seq):
                    cc=(start+k)%W
                    out[si][cc]=v
    return out
