    I=np.array(I); H,W=I.shape
    templ=[]; seeds=[]
    for r in range(H):
        c=0
        while c<W:
            if I[r][c]!=0:
                s=c
                while c<W and I[r][c]!=0: c+=1
                if c-s>=2: templ.append((r,s,I[r][s:c]))
                else: seeds.append((r,s))
            else: c+=1
    out=[[int(x) for x in row] for row in I]
    for r,s in seeds:
        v=int(I[r][s])
        cands=[(tr,st,[int(x) for x in p]) for tr,st,p in templ if v in p and len(p)>1]
        if len(cands)!=1: continue
        tr,st,p=cands[0]
        idx=p.index(v)
        start=s-idx
        for j,vv in enumerate(p):
            cc=start+j
            if 0<=cc<W and out[r][cc]==0 or I[r][cc]==0: pass
        for j,vv in enumerate(p):
            cc=start+j
            if 0<=cc<W and I[r][cc]==0: out[r][cc]=vv
    return out
